from bisect import bisect_left, bisect_right
from functools import lru_cache

class Solution:
    def longestPalindromeSubseq(self, s: str) -> int:
        n = len(s)
        pos = [[] for _ in range(26)]
        for i, ch in enumerate(s):
            pos[ord(ch) - 97].append(i)

        @lru_cache(maxsize=None)
        def dfs(l, r, prev):
            best = 0
            for c in range(26):
                if c == prev:
                    continue
                lst = pos[c]
                li = bisect_left(lst, l)
                if li == len(lst):
                    continue
                ri = bisect_right(lst, r) - 1
                if ri <= li:
                    continue
                best = max(best, 2 + dfs(lst[li] + 1, lst[ri] - 1, c))
            return best

        return dfs(0, n - 1, 26)

