class Solution {
public:
    int memo[250][250][27];
    int nxt[251][26], prv[250][26];
    int n;

    int dfs(int l, int r, int prev) {
        if (l >= r) return 0;
        int &res = memo[l][r][prev];
        if (res != -1) return res;
        res = 0;
        for (int c = 0; c < 26; c++) {
            if (c == prev) continue;
            int li = nxt[l][c], ri = prv[r][c];
            if (li < ri) res = max(res, 2 + dfs(li + 1, ri - 1, c));
        }
        return res;
    }

    int longestPalindromeSubseq(string s) {
        n = s.size();
        memset(memo, -1, sizeof(memo));
        for (int c = 0; c < 26; c++) nxt[n][c] = n;
        for (int i = n - 1; i >= 0; i--)
            for (int c = 0; c < 26; c++)
                nxt[i][c] = (s[i] - 'a' == c) ? i : nxt[i + 1][c];
        for (int c = 0; c < 26; c++) prv[0][c] = (s[0] - 'a' == c) ? 0 : -1;
        for (int i = 1; i < n; i++)
            for (int c = 0; c < 26; c++)
                prv[i][c] = (s[i] - 'a' == c) ? i : prv[i - 1][c];
        return dfs(0, n - 1, 26);
    }
};

