class Solution {
    private int[][][] memo;
    private int[][] nxt, prv;
    private int n;

    public int longestPalindromeSubseq(String s) {
        n = s.length();
        memo = new int[n][n][27];
        for (int[][] a : memo)
            for (int[] b : a) Arrays.fill(b, -1);
        nxt = new int[n + 1][26];
        prv = new int[n][26];
        for (int c = 0; c < 26; c++) nxt[n][c] = n;
        for (int i = n - 1; i >= 0; i--)
            for (int c = 0; c < 26; c++)
                nxt[i][c] = (s.charAt(i) - 'a' == c) ? i : nxt[i + 1][c];
        for (int c = 0; c < 26; c++) prv[0][c] = (s.charAt(0) - 'a' == c) ? 0 : -1;
        for (int i = 1; i < n; i++)
            for (int c = 0; c < 26; c++)
                prv[i][c] = (s.charAt(i) - 'a' == c) ? i : prv[i - 1][c];
        return dfs(0, n - 1, 26);
    }

    private int dfs(int l, int r, int prev) {
        if (l >= r) return 0;
        if (memo[l][r][prev] != -1) return memo[l][r][prev];
        int res = 0;
        for (int c = 0; c < 26; c++) {
            if (c == prev) continue;
            int li = nxt[l][c], ri = prv[r][c];
            if (li < ri) res = Math.max(res, 2 + dfs(li + 1, ri - 1, c));
        }
        memo[l][r][prev] = res;
        return res;
    }
}

