class Solution:
    def longestPalindromeSubseq(self, s: str) -> int:
        n = len(s)
        if n < 2:
            return 0
        nxt = [[n] * 26 for _ in range(n + 1)]
        prv = [[-1] * 26 for _ in range(n)]
        for i in range(n - 1, -1, -1):
            si = ord(s[i]) - 97
            row_nxt, row_prv = nxt[i], prv[i]
            for c in range(26):
                row_nxt[c] = i if c == si else nxt[i + 1][c]
                row_prv[c] = i if c == si else (prv[i - 1][c] if i else -1)
        dp = [[[0] * 27 for _ in range(n)] for _ in range(n)]
        for l in range(n - 2, -1, -1):
            nxt_l = nxt[l]
            for r in range(l + 1, n):
                cand = [0] * 26
                for c in range(26):
                    li = nxt_l[c]
                    ri = prv[r][c]
                    if li < ri:
                        inner = dp[li + 1][ri - 1][c] if li + 1 <= ri - 1 else 0
                        cand[c] = 2 + inner
                cur = dp[l][r]
                run = 0
                best = 0
                for c in range(26):
                    cur[c] = run
                    if cand[c] > best:
                        best = cand[c]
                    if cand[c] > run:
                        run = cand[c]
                cur[26] = best
                run = 0
                for c in range(25, -1, -1):
                    if run > cur[c]:
                        cur[c] = run
                    if cand[c] > run:
                        run = cand[c]
        return dp[0][n - 1][26]

